                        self.start_review(t, ps, p, stage, &ctx, &cwd, lane.as_deref(), now_ms)?;
                    }
                }
            }
            if !t.active() {
                return Ok(());
            }
        }
        if all_complete {
            self.advance(t, now_ms)?;
        }
        Ok(())
    }

